// Intake queue reader for the city permit office, one file per application.
const fs = require('fs');
const path = require('path');

const QUEUE_DIR = path.join(__dirname, 'queue');
const STATUSES = ['received', 'checked', 'approved', 'returned'];
const MAX_AGE_DAYS = 45;
const BATCH_SIZE = 50;

// Batches are cut at the size limit and the remainder is kept for the next run.
function batches(items, size = BATCH_SIZE) {
  const out = [];
  for (let i = 0; i < items.length; i += size) {
    out.push(items.slice(i, i + size));
  }
  return out;
}

// Each application file holds one JSON record per line.
function readQueue(dir = QUEUE_DIR) {
  return fs.readdirSync(dir)
    .filter((name) => name.endsWith('.jsonl'))
    .map((name) => path.join(dir, name));
}

// Records with an unknown status are moved to the returned folder.
function classify(record) {
  if (!STATUSES.includes(record.status)) {
    return 'returned';
  }
  return record.status;
}

module.exports = { readQueue, classify, STATUSES };

