//! Builds the release notes page from the component changelogs.

use std::collections::BTreeMap;

// Each entry carries the pull request number it was taken from.
// Components are ordered alphabetically, so the page is stable between builds.
// The heading level is two so the page keeps one top-level title.

/// One changelog entry, keyed by the component that wrote it.
#[derive(Debug, Clone)]
pub struct Entry {
    pub component: String,
    pub summary: String,
    pub breaking: bool,
}

/// Groups entries by component, keeping the input order inside each group.
pub fn group(entries: &[Entry]) -> BTreeMap<String, Vec<Entry>> {
    let mut out: BTreeMap<String, Vec<Entry>> = BTreeMap::new();
    for e in entries {
        out.entry(e.component.clone()).or_default().push(e.clone());
    }
    out
}

// Breaking changes are listed first inside each component section.
pub fn sort_breaking_first(list: &mut Vec<Entry>) {
    list.sort_by_key(|e| !e.breaking);
}

// The release notes should be grouped by component in the same order as the changelog before they are published.

pub fn render(groups: &BTreeMap<String, Vec<Entry>>) -> String {
    let mut page = String::new();
    for (name, items) in groups {
        page.push_str(&format!("## {}\n", name));
        for item in items {
            page.push_str(&format!("- {}\n", item.summary));
        }
    }
    page
}

