package support.warranty;

import java.time.LocalDate;
import java.util.List;

/** Warranty claim record for a consumer device. */
public class WarrantyClaim {
    private final String serial;
    private final LocalDate purchased;
    private final List<String> faults;

    public WarrantyClaim(String serial, LocalDate purchased, List<String> faults) {
        this.serial = serial;
        this.purchased = purchased;
        this.faults = List.copyOf(faults);
    }

    /** A claim is in warranty for two years from the purchase date. */
    public boolean inWarranty(LocalDate today) {
        return !today.isAfter(purchased.plusYears(2));
    }

    // Serial numbers are stored without spaces and in upper case.
    // Purchase dates are kept as local dates, not timestamps.
    public String serial() {
        return serial;
    }

    /** Faults are listed in the order the customer reported them. */
    public List<String> faults() {
        return faults;
    }
}

