from dataclasses import dataclass
from datetime import datetime

@dataclass
class Fixture:
    division: str
    kickoff: datetime
    home: str
    away: str
    venue: str
    contact_phone: str


def sort_by_kickoff(fixtures):
    '''Returns the fixtures in kickoff order, earliest first.'''
    return sorted(fixtures, key=lambda f: f.kickoff)


def count_divisions(fixtures):
    '''Gives the number of distinct divisions in the fixture list.'''
    return len({f.division for f in fixtures})


def venue_summary(fixtures):
    '''Counts the fixtures booked at each venue.'''
    counts = {}
    for f in fixtures:
        counts[f.venue] = counts.get(f.venue, 0) + 1
    return counts


