'''Release-notes checker for the packaging team.

The checker compares the changelog against the tags that were pushed.
'''

import subprocess


def is_release_tag(name):
    return name.startswith('v') and name[1:].replace('.', '').isdigit()


def latest_tag(tags):
    '''Gives the highest release tag by numeric order.'''
    if not tags:
        return None
    return max(tags, key=lambda t: [int(p) for p in t[1:].split('.')])


def pushed_tags(repo):
    out = subprocess.run(
        ['git', '-C', repo, 'tag', '--list'],
        capture_output=True, text=True, check=True,
    ).stdout
    return [t for t in out.split() if is_release_tag(t)]


def missing_entries(changelog_text, tags):
    '''Gives the tags that have no heading in the changelog.'''
    return [t for t in tags if '## ' + t not in changelog_text]

